<!DOCTYPE html>
<html lang="pt-BR">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <meta name="robots" content="index,follow">
    <meta name="description" content="Peter Tecnet Developer Portal: crie aplicações, chaves de API, scopes, webhooks e acompanhe métricas de integração.">
    <link rel="canonical" href="https://api.petertecnet.com.br/developers">
    <title>Developer Portal | Peter Tecnet API</title>
    <style>
        :root{color-scheme:dark;--bg:#050816;--surface:#0d142b;--surface2:#111b38;--line:#26324f;--text:#f8fafc;--muted:#9eacc5;--primary:#6f92ff;--accent:#55e8c4;--danger:#ff7b8e}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 12% 0,#172a5d 0,transparent 32%),var(--bg);color:var(--text);font-family:Inter,system-ui,sans-serif;line-height:1.5}a{color:inherit}.shell{width:min(1180px,calc(100% - 28px));margin:auto}.topbar{position:sticky;top:0;z-index:10;background:#050816dc;border-bottom:1px solid var(--line);backdrop-filter:blur(16px)}.nav{min-height:68px;display:flex;align-items:center;justify-content:space-between;gap:16px}.brand{text-decoration:none;font-weight:900}.navlinks{display:flex;gap:14px;color:var(--muted);font-size:14px}.navlinks a{text-decoration:none}.hero{padding:64px 0 28px}.eyebrow{color:var(--accent);font-size:12px;text-transform:uppercase;font-weight:900;letter-spacing:.12em}h1{font-size:clamp(2.5rem,7vw,5.2rem);line-height:.95;letter-spacing:-.055em;margin:12px 0 18px}.hero p{max-width:760px;color:var(--muted);font-size:1.08rem}.panel{background:#0d142bd9;border:1px solid var(--line);border-radius:22px;padding:24px;box-shadow:0 20px 60px #0005;margin-bottom:18px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.field{display:grid;gap:7px;margin-bottom:14px}label{font-size:13px;font-weight:800;color:#cad5e8}input,select,textarea{width:100%;border:1px solid var(--line);background:#070c1c;color:var(--text);border-radius:12px;padding:12px 13px;outline:none}input:focus,select:focus,textarea:focus{border-color:var(--primary)}textarea{min-height:84px;resize:vertical}.btn{border:1px solid var(--line);background:#121d3c;color:var(--text);border-radius:12px;padding:11px 15px;font-weight:850;cursor:pointer}.btn:hover{border-color:#5877c7}.btn.primary{background:linear-gradient(135deg,#4d72e1,#7697ff);border-color:transparent}.btn.danger{color:#ffd8de;border-color:#6c3140;background:#26101a}.btn.small{padding:8px 10px;font-size:12px}.actions{display:flex;flex-wrap:wrap;gap:8px}.notice{border-left:3px solid var(--primary);background:#5f8cff13;padding:13px 15px;border-radius:0 12px 12px 0;color:#cad7ec;font-size:14px}.error{border-left-color:var(--danger);background:#ff637413}.success{border-left-color:var(--accent);background:#55e8c413}.scope-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.scope{display:flex;gap:8px;align-items:flex-start;padding:10px;border:1px solid var(--line);border-radius:12px;background:#070c1b}.scope input{width:auto;margin-top:4px}.scope span{font-size:12px;color:var(--muted)}.client-list{display:grid;gap:12px}.client{padding:18px;border:1px solid var(--line);border-radius:17px;background:#080e20}.client-head{display:flex;justify-content:space-between;gap:14px;align-items:flex-start}.client h3{margin:0 0 3px}.meta{color:var(--muted);font-size:12px;overflow-wrap:anywhere}.badges{display:flex;gap:6px;flex-wrap:wrap;margin:12px 0}.badge{font-size:11px;font-weight:850;padding:5px 8px;border-radius:999px;background:#5f8cff16;border:1px solid #5f8cff38;color:#b9caff}.badge.green{background:#55e8c412;border-color:#55e8c43d;color:#9ff4df}.statgrid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.stat{border:1px solid var(--line);border-radius:14px;padding:13px;background:#080e20}.stat strong{font-size:1.25rem;display:block}.stat span{color:var(--muted);font-size:11px}.tablewrap{overflow:auto}.table{width:100%;border-collapse:collapse;font-size:13px}.table th,.table td{text-align:left;border-bottom:1px solid var(--line);padding:10px;white-space:nowrap}.table th{color:#aebbd0}.hidden{display:none!important}.secret{word-break:break-all;font-family:ui-monospace,monospace;background:#060a15;border:1px dashed #5272bd;padding:14px;border-radius:12px;margin:12px 0}.modal{position:fixed;inset:0;z-index:40;background:#000b;display:grid;place-items:center;padding:20px}.modalbox{width:min(650px,100%);background:#0d142b;border:1px solid var(--line);border-radius:20px;padding:24px}.footer{padding:40px 0 60px;color:var(--muted);font-size:13px}@media(max-width:800px){.grid,.scope-grid{grid-template-columns:1fr}.statgrid{grid-template-columns:repeat(2,1fr)}.client-head{display:block}.client-head .actions{margin-top:12px}.navlinks{display:none}}
    </style>
</head>
<body>
<header class="topbar"><div class="shell nav"><a class="brand" href="/">Peter Tecnet API</a><nav class="navlinks"><a href="/docs">Documentação</a><a href="/status">Status</a><a href="/changelog">Changelog</a></nav><button id="logoutBtn" class="btn small hidden">Sair</button></div></header>
<main class="shell">
    <section class="hero"><span class="eyebrow">Developer Platform</span><h1>Construa com a<br>Peter Tecnet.</h1><p>Gerencie aplicações externas, ambientes, scopes, chaves, origens de navegador, webhooks, logs e métricas sem depender de alterações no código da API.</p></section>

    <section id="loginPanel" class="panel" style="max-width:560px">
        <h2>Acessar o portal</h2><p class="meta">Use sua conta Peter Tecnet. O token da sessão fica apenas no sessionStorage deste navegador.</p>
        <form id="loginForm">
            <div class="field"><label for="username">E-mail, usuário, CPF ou telefone</label><input id="username" autocomplete="username" required></div>
            <div class="field"><label for="password">Senha</label><input id="password" type="password" autocomplete="current-password" required></div>
            <button class="btn primary" type="submit">Entrar</button>
        </form>
        <div id="loginMessage" class="notice hidden" style="margin-top:14px"></div>
    </section>

    <div id="dashboard" class="hidden">
        <div class="grid">
            <section class="panel">
                <h2>Nova aplicação</h2>
                <form id="clientForm">
                    <div class="field"><label>Nome da integração</label><input id="clientName" maxlength="120" required placeholder="Ex.: Meu ERP"></div>
                    <div class="field"><label>Ambiente</label><select id="environment"><option value="sandbox">Sandbox</option><option value="production">Produção</option></select></div>
                    <div class="field"><label>Origens de navegador</label><textarea id="origins" placeholder="https://app.exemplo.com&#10;Uma origem por linha. Deixe vazio para uso apenas server-to-server."></textarea></div>
                    <div class="field"><label>Scopes</label><div id="scopeGrid" class="scope-grid"></div></div>
                    <button class="btn primary" type="submit">Criar aplicação e chave</button>
                </form>
                <div id="createMessage" class="notice hidden" style="margin-top:14px"></div>
            </section>
            <section class="panel"><h2>Boas práticas</h2><div class="notice">Chaves <strong>live</strong> devem ficar somente no backend. Para aplicações no navegador, cadastre a origem e inclua <code>client_id</code> na query string para o preflight CORS.</div><p class="meta">Use sandbox durante o desenvolvimento, aplique o menor conjunto de scopes possível e faça rotação imediata quando houver suspeita de exposição.</p><div class="actions"><a class="btn small" href="/docs#autenticacao">Autenticação</a><a class="btn small" href="/openapi.json">OpenAPI</a><a class="btn small" href="/terms">Termos</a></div></section>
        </div>

        <section class="panel"><div class="client-head"><div><h2>Suas aplicações</h2><p class="meta">Credenciais e políticas independentes por integração.</p></div><button id="refreshBtn" class="btn small">Atualizar</button></div><div id="clientList" class="client-list"></div></section>

        <section id="detailPanel" class="panel hidden"><div class="client-head"><div><h2 id="detailTitle">Aplicação</h2><p id="detailMeta" class="meta"></p></div><div class="actions"><button id="rotateBtn" class="btn small">Rotacionar chave</button><button id="disableBtn" class="btn danger small">Desativar</button></div></div>
            <h3>Métricas — últimos 7 dias</h3><div id="metrics" class="statgrid"></div>
            <h3>Últimas requisições</h3><div class="tablewrap"><table class="table"><thead><tr><th>Quando</th><th>Método</th><th>Endpoint</th><th>Status</th><th>Latência</th><th>Request ID</th></tr></thead><tbody id="logsBody"></tbody></table></div>
            <h3>Webhooks</h3><form id="webhookForm" class="grid"><div><div class="field"><label>URL HTTPS pública</label><input id="webhookUrl" type="url" placeholder="https://app.exemplo.com/webhooks/peter" required></div><div class="field"><label>Eventos</label><div id="eventGrid" class="scope-grid"></div></div><button class="btn primary" type="submit">Adicionar webhook</button></div><div><div id="webhookList" class="client-list"></div></div></form>
        </section>
    </div>
</main>
<footer class="shell footer">Peter Tecnet Developer Platform · <a href="/privacy">Privacidade</a> · <a href="/deprecation">Depreciação</a></footer>

<div id="secretModal" class="modal hidden"><div class="modalbox"><h2>Segredo exibido uma única vez</h2><p class="meta">Copie e armazene em um gerenciador de segredos. A Peter Tecnet guarda somente o hash da API key.</p><div id="secretValue" class="secret"></div><div class="actions"><button id="copySecret" class="btn primary">Copiar</button><button id="closeSecret" class="btn">Fechar</button></div></div></div>

<script>
const state={token:sessionStorage.getItem('pt_dev_token'),scopes:{},events:[],clients:[],selected:null};
const $=id=>document.getElementById(id);
function message(el,text,type=''){el.textContent=text;el.className='notice '+type;el.classList.remove('hidden')}
async function api(path,options={}){const headers={'Accept':'application/json','Content-Type':'application/json',...(options.headers||{})};if(state.token)headers.Authorization='Bearer '+state.token;const response=await fetch(path,{...options,headers});let json={};try{json=await response.json()}catch{}if(response.status===401&&path!='/api/auth/login'){logout();throw new Error('Sua sessão expirou. Entre novamente.')}if(!response.ok){const msg=json?.error?.message||json?.message||json?.error||'Falha na operação.';throw new Error(typeof msg==='string'?msg:'Falha na operação.')}return json}
function showSecret(value){$('secretValue').textContent=value;$('secretModal').classList.remove('hidden')}
function logout(){state.token=null;sessionStorage.removeItem('pt_dev_token');$('dashboard').classList.add('hidden');$('logoutBtn').classList.add('hidden');$('loginPanel').classList.remove('hidden');$('detailPanel').classList.add('hidden')}
async function bootstrap(){if(!state.token)return;try{const [scopes,events,clients]=await Promise.all([api('/api/v1/developer/scopes'),api('/api/v1/developer/webhook-events'),api('/api/v1/developer/clients')]);state.scopes=scopes.data||{};state.events=events.data||[];state.clients=clients.data||[];renderScopes();renderEvents();renderClients();$('loginPanel').classList.add('hidden');$('dashboard').classList.remove('hidden');$('logoutBtn').classList.remove('hidden')}catch(e){logout();message($('loginMessage'),e.message,'error')}}
function renderScopes(){const entries=Object.entries(state.scopes);$('scopeGrid').innerHTML=entries.map(([scope,desc],i)=>`<label class="scope"><input type="checkbox" name="scope" value="${scope}" ${i<2?'checked':''}><span><strong>${scope}</strong><br>${desc}</span></label>`).join('')}
function renderEvents(){$('eventGrid').innerHTML=state.events.map((event,i)=>`<label class="scope"><input type="checkbox" name="event" value="${event}" ${i===0?'checked':''}><span>${event}</span></label>`).join('')}
function escapeHtml(value){return String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function renderClients(){if(!state.clients.length){$('clientList').innerHTML='<div class="notice">Você ainda não criou aplicações de desenvolvedor.</div>';return}$('clientList').innerHTML=state.clients.map(c=>`<article class="client"><div class="client-head"><div><h3>${escapeHtml(c.name)}</h3><div class="meta">${escapeHtml(c.client_id)}</div></div><div class="actions"><button class="btn small" onclick="openClient(${c.id})">Gerenciar</button></div></div><div class="badges"><span class="badge green">${c.environment}</span><span class="badge">${c.status}</span><span class="badge">${c.rate_limit_per_minute}/min</span>${c.scopes.map(s=>`<span class="badge">${escapeHtml(s)}</span>`).join('')}</div><div class="meta">Chaves: ${(c.keys||[]).map(k=>escapeHtml(k.prefix)+'••••').join(', ')||'nenhuma'} · Último uso: ${c.last_used_at?new Date(c.last_used_at).toLocaleString('pt-BR'):'ainda não usado'}</div></article>`).join('')}
async function refreshClients(){const clients=await api('/api/v1/developer/clients');state.clients=clients.data||[];renderClients()}
async function openClient(id){state.selected=id;const c=state.clients.find(x=>x.id===id);$('detailTitle').textContent=c?.name||'Aplicação';$('detailMeta').textContent=(c?.client_id||'')+' · '+(c?.environment||'');$('detailPanel').classList.remove('hidden');const [metrics,logs,webhooks]=await Promise.all([api(`/api/v1/developer/clients/${id}/metrics?days=7`),api(`/api/v1/developer/clients/${id}/logs?per_page=20`),api(`/api/v1/developer/clients/${id}/webhooks`)]);renderMetrics(metrics.data||{});renderLogs(logs.data||[]);renderWebhooks(webhooks.data||[]);$('detailPanel').scrollIntoView({behavior:'smooth',block:'start'})}
function renderMetrics(m){$('metrics').innerHTML=`<div class="stat"><strong>${m.requests||0}</strong><span>requisições</span></div><div class="stat"><strong>${m.successes||0}</strong><span>sucessos</span></div><div class="stat"><strong>${m.server_errors||0}</strong><span>erros 5xx</span></div><div class="stat"><strong>${m.latency_ms?.p95||0}ms</strong><span>latência p95</span></div>`}
function renderLogs(logs){$('logsBody').innerHTML=logs.map(l=>`<tr><td>${new Date(l.created_at).toLocaleString('pt-BR')}</td><td>${escapeHtml(l.method)}</td><td>${escapeHtml(l.path)}</td><td>${l.status}</td><td>${l.duration_ms}ms</td><td>${escapeHtml(l.request_id||'')}</td></tr>`).join('')||'<tr><td colspan="6">Sem requisições registradas.</td></tr>'}
function renderWebhooks(list){$('webhookList').innerHTML=list.map(w=>`<div class="client"><strong>${escapeHtml(w.url)}</strong><div class="meta">${w.events.map(escapeHtml).join(', ')}</div><div class="badges"><span class="badge">${w.status}</span></div><div class="actions"><button type="button" class="btn small" onclick="testWebhook()">Enviar teste</button><button type="button" class="btn danger small" onclick="disableWebhook(${w.id})">Desativar</button></div></div>`).join('')||'<div class="notice">Nenhum webhook cadastrado.</div>'}
$('loginForm').addEventListener('submit',async e=>{e.preventDefault();try{const json=await api('/api/auth/login',{method:'POST',body:JSON.stringify({username:$('username').value,password:$('password').value})});state.token=json?.token?.access_token;if(!state.token)throw new Error('Token não recebido.');sessionStorage.setItem('pt_dev_token',state.token);$('password').value='';await bootstrap()}catch(err){message($('loginMessage'),err.message,'error')}})
$('clientForm').addEventListener('submit',async e=>{e.preventDefault();try{const scopes=[...document.querySelectorAll('input[name="scope"]:checked')].map(x=>x.value);const allowed_origins=$('origins').value.split(/\n+/).map(x=>x.trim()).filter(Boolean);const json=await api('/api/v1/developer/clients',{method:'POST',body:JSON.stringify({name:$('clientName').value,environment:$('environment').value,scopes,allowed_origins})});showSecret(json.data.api_key);$('clientForm').reset();renderScopes();message($('createMessage'),'Aplicação criada. A chave completa está no quadro de segredo.','success');await refreshClients()}catch(err){message($('createMessage'),err.message,'error')}})
$('webhookForm').addEventListener('submit',async e=>{e.preventDefault();if(!state.selected)return;try{const events=[...document.querySelectorAll('input[name="event"]:checked')].map(x=>x.value);const json=await api(`/api/v1/developer/clients/${state.selected}/webhooks`,{method:'POST',body:JSON.stringify({url:$('webhookUrl').value,events})});showSecret(json.data.signing_secret);$('webhookUrl').value='';await openClient(state.selected)}catch(err){alert(err.message)}})
async function testWebhook(){if(!state.selected)return;try{const json=await api(`/api/v1/developer/clients/${state.selected}/webhooks/test`,{method:'POST',body:'{}'});alert(`${json.data.queued_deliveries} entrega(s) enfileirada(s).`)}catch(e){alert(e.message)}}
async function disableWebhook(id){if(!state.selected||!confirm('Desativar este webhook?'))return;try{await api(`/api/v1/developer/clients/${state.selected}/webhooks/${id}`,{method:'DELETE'});await openClient(state.selected)}catch(e){alert(e.message)}}
$('rotateBtn').addEventListener('click',async()=>{if(!state.selected||!confirm('Rotacionar a chave e revogar as chaves ativas atuais?'))return;try{const json=await api(`/api/v1/developer/clients/${state.selected}/keys/rotate`,{method:'POST',body:JSON.stringify({revoke_existing:true})});showSecret(json.data.api_key);await refreshClients()}catch(e){alert(e.message)}})
$('disableBtn').addEventListener('click',async()=>{if(!state.selected||!confirm('Desativar esta aplicação e revogar suas chaves?'))return;try{await api(`/api/v1/developer/clients/${state.selected}`,{method:'DELETE'});$('detailPanel').classList.add('hidden');state.selected=null;await refreshClients()}catch(e){alert(e.message)}})
$('refreshBtn').addEventListener('click',refreshClients);$('logoutBtn').addEventListener('click',logout);$('closeSecret').addEventListener('click',()=>{$('secretValue').textContent='';$('secretModal').classList.add('hidden')});$('copySecret').addEventListener('click',async()=>{await navigator.clipboard.writeText($('secretValue').textContent);$('copySecret').textContent='Copiado'});
bootstrap();
</script>
</body>
</html>
